const http = require("http");
const { spawn } = require("child_process");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
const APP = "aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa";
const A = "11111111-1111-1111-1111-111111111111";
const B = "22222222-2222-2222-2222-222222222222";
function inst(id) { return { id, location: "iad01", app_version: 1, created_at: "2025-06-01T10:00:00Z" }; }
let requests = 0;
const server = http.createServer((req, res) => {
  const url = new URL(req.url, "http://x");
  res.setHeader("content-type", "application/json");
  if (!url.pathname.endsWith("/dash/applications/" + APP + "/instances")) {
    res.statusCode = 404;
    res.end(JSON.stringify({ success: false, result: null, errors: [{ code: 1, message: "unexpected " + url.pathname }], messages: [] }));
    return;
  }
  requests++;
  const second = url.searchParams.get("page_token") === "next-page";
  res.end(JSON.stringify({ success: true, result: { instances: [inst(second ? B : A)], durable_objects: [] }, result_info: second ? { per_page: 1 } : { per_page: 1, next_page_token: "next-page" }, errors: [], messages: [] }));
});
server.listen(0, "127.0.0.1", () => {
  const port = server.address().port;
  const env = Object.assign({}, process.env, { CLOUDFLARE_API_BASE_URL: "http://127.0.0.1:" + port + "/client/v4", CLOUDFLARE_API_TOKEN: "test-token", CLOUDFLARE_ACCOUNT_ID: "0123456789abcdef0123456789abcdef", WRANGLER_SEND_METRICS: "false", CI: "true", NO_COLOR: "1" });
  const child = spawn(process.execPath, ["/w/node_modules/wrangler/bin/wrangler.js", "containers", "instances", APP, "--search", B, "--json", "--per-page", "1"], { cwd: "/tmp", env });
  let out = "", err = "";
  child.stdout.on("data", (d) => { out += d; });
  child.stderr.on("data", (d) => { err += d; });
  const timer = setTimeout(() => { child.kill("SIGKILL"); broken("wrangler timed out"); }, 80000);
  child.on("close", (code) => {
    clearTimeout(timer);
    server.close();
    const all = out + err;
    if (code !== 0) {
      if (/Unknown arguments?:.*search/.test(all)) symptom("wrangler containers instances rejects --search");
      broken("wrangler exited " + code + ": " + all.slice(-500));
    }
    let data;
    try { data = JSON.parse(out.slice(out.indexOf("["))); } catch (e) { broken("stdout is not JSON: " + out.slice(-500)); }
    if (!Array.isArray(data)) broken("JSON output is not a top-level array");
    if (requests !== 2) broken("expected 2 page requests, got " + requests);
    if (data.length !== 1 || data[0].id !== B) broken("unexpected search result: " + JSON.stringify(data));
    console.log("OK: --search found the instance on the second page as a top-level JSON array");
  });
});

